using System.Security.Claims;using System.Text.Encodings.Web;using Microsoft.AspNetCore.Authentication;using Microsoft.Extensions.Options;
namespace AiGateway.Api.Middleware;
public sealed class HeaderAuthenticationHandler(IOptionsMonitor<AuthenticationSchemeOptions> options,ILoggerFactory logger,UrlEncoder encoder):AuthenticationHandler<AuthenticationSchemeOptions>(options,logger,encoder)
{protected override Task<AuthenticateResult> HandleAuthenticateAsync(){var company=Request.Headers["X-Company-Id"].FirstOrDefault();var user=Request.Headers["X-User-Id"].FirstOrDefault();var version=Request.Headers["X-Erp-Version"].FirstOrDefault();if(string.IsNullOrWhiteSpace(company)||string.IsNullOrWhiteSpace(user)||string.IsNullOrWhiteSpace(version))return Task.FromResult(AuthenticateResult.NoResult());var claims=new List<Claim>{new(ClaimTypes.NameIdentifier,user),new("company_id",company),new("erp_version",version),new("language",Request.Headers["X-Language"].FirstOrDefault()??"pt-BR")};foreach(var permission in Request.Headers["X-Permissions"].ToString().Split(',',StringSplitOptions.RemoveEmptyEntries|StringSplitOptions.TrimEntries))claims.Add(new("permission",permission));return Task.FromResult(AuthenticateResult.Success(new AuthenticationTicket(new ClaimsPrincipal(new ClaimsIdentity(claims,Scheme.Name)),Scheme.Name)));}}
